// Leak: DbContext not disposed
public async Task<List<Order>> GetOrdersAsync()
{
    var ctx = new AppDbContext(); // Never disposed!
    return await ctx.Orders.Where(o => o.UserId == _userId).ToListAsync();
}

// Fix: use using statement
public async Task<List<Order>> GetOrdersAsync()
{
    await using var ctx = new AppDbContext();
    return await ctx.Orders.Where(o => o.UserId == _userId).ToListAsync();
}
